"use client"

import { useState } from "react"
import Link from "next/link"
import { Button } from "@/components/ui/button"
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardDescription,
} from "@/components/ui/card"
import {
  ArrowLeft,
  Loader2,
  FileText,
  ListOrdered,
  AlignLeft,
  BookOpen,
  ImageIcon,
  ImagePlus,
  Copy,
  Check,
  Trash2,
  Eye,
} from "lucide-react"
import { toast } from "sonner"

type Project = {
  id: string
  productName: string
  category: string | null
  features: string | null
  sellingPoints: string | null
  keywords: string | null
  useScenario: string | null
  targetAudience: string | null
  priceRange: string | null
  brandTone: string | null
  platform: string
  language: string
  createdAt: Date
  updatedAt: Date
  records: Array<{
    id: string
    contentType: string
    content: string | null
    imageUrl: string | null
    prompt: string | null
    createdAt: Date
  }>
}

const generationTypes = [
  {
    key: "title",
    label: "商品标题",
    desc: "生成SEO优化的产品标题",
    icon: FileText,
    gradient: "from-blue-500/20 to-blue-600/5",
    iconColor: "text-blue-600 dark:text-blue-400",
    borderColor: "border-blue-200/50 dark:border-blue-800/30",
  },
  {
    key: "bulletPoints",
    label: "要点描述",
    desc: "生成产品核心卖点列表",
    icon: ListOrdered,
    gradient: "from-emerald-500/20 to-emerald-600/5",
    iconColor: "text-emerald-600 dark:text-emerald-400",
    borderColor: "border-emerald-200/50 dark:border-emerald-800/30",
  },
  {
    key: "shortDesc",
    label: "短描述",
    desc: "生成简洁的产品介绍",
    icon: AlignLeft,
    gradient: "from-violet-500/20 to-violet-600/5",
    iconColor: "text-violet-600 dark:text-violet-400",
    borderColor: "border-violet-200/50 dark:border-violet-800/30",
  },
  {
    key: "longDesc",
    label: "长描述",
    desc: "生成详细的产品描述",
    icon: BookOpen,
    gradient: "from-amber-500/20 to-amber-600/5",
    iconColor: "text-amber-600 dark:text-amber-400",
    borderColor: "border-amber-200/50 dark:border-amber-800/30",
  },
  {
    key: "mainImage",
    label: "商品主图",
    desc: "生成产品主图提示词",
    icon: ImageIcon,
    gradient: "from-pink-500/20 to-pink-600/5",
    iconColor: "text-pink-600 dark:text-pink-400",
    borderColor: "border-pink-200/50 dark:border-pink-800/30",
  },
  {
    key: "sceneImage",
    label: "场景图",
    desc: "生成产品使用场景图",
    icon: ImagePlus,
    gradient: "from-cyan-500/20 to-cyan-600/5",
    iconColor: "text-cyan-600 dark:text-cyan-400",
    borderColor: "border-cyan-200/50 dark:border-cyan-800/30",
  },
]

const platformLabels: Record<string, string> = {
  amazon: "Amazon",
  shopify: "Shopify",
  tiktok: "TikTok Shop",
}

const languageLabels: Record<string, string> = {
  zh: "中文",
  en: "English",
  es: "Español",
}

const contentTypeLabels: Record<string, string> = {
  title: "商品标题",
  bulletPoints: "要点描述",
  shortDesc: "短描述",
  longDesc: "长描述",
  mainImage: "商品主图",
  sceneImage: "场景图",
}

export function ProjectDetail({ project }: { project: Project }) {
  const [generating, setGenerating] = useState<string | null>(null)
  const [records, setRecords] = useState(project.records)
  const [copiedId, setCopiedId] = useState<string | null>(null)

  async function handleGenerate(contentType: string) {
    setGenerating(contentType)

    try {
      const res = await fetch("/api/generate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          projectId: project.id,
          contentType,
        }),
      })

      const data = await res.json()
      if (!res.ok) throw new Error(data.error)

      setRecords((prev) => [data.record, ...prev])
      toast.success(`${contentTypeLabels[contentType] || contentType} 生成成功！`)
    } catch {
      toast.error("生成失败，请稍后再试")
    } finally {
      setGenerating(null)
    }
  }

  async function handleDelete(recordId: string) {
    try {
      const res = await fetch(`/api/records/${recordId}`, {
        method: "DELETE",
      })
      if (!res.ok) throw new Error()
      setRecords((prev) => prev.filter((r) => r.id !== recordId))
      toast.success("已删除")
    } catch {
      toast.error("删除失败")
    }
  }

  function handleCopy(content: string | null) {
    if (!content) return
    navigator.clipboard.writeText(content)
    toast.success("已复制到剪贴板")
  }

  const groupedRecords: Record<string, typeof records> = {}
  for (const record of records) {
    const key = record.contentType
    if (!groupedRecords[key]) groupedRecords[key] = []
    groupedRecords[key].push(record)
  }

  return (
    <div className="mx-auto max-w-5xl px-4 sm:px-6 lg:px-8 py-8">
      {/* Back */}
      <Link
        href="/dashboard"
        className="inline-flex items-center gap-1 text-sm text-muted-foreground hover:text-foreground transition-colors mb-6"
      >
        <ArrowLeft className="size-4" />
        返回工作台
      </Link>

      {/* Project Info Header */}
      <div className="mb-8">
        <div className="flex items-start justify-between">
          <div className="flex-1 min-w-0">
            <h1 className="text-2xl font-bold tracking-tight">
              {project.productName}
            </h1>
            <div className="flex flex-wrap items-center gap-2 mt-2">
              <span className="inline-flex items-center rounded-full bg-primary/10 px-2.5 py-0.5 text-xs font-medium text-primary">
                {platformLabels[project.platform] || project.platform}
              </span>
              <span className="inline-flex items-center rounded-full bg-muted px-2.5 py-0.5 text-xs font-medium text-muted-foreground">
                {languageLabels[project.language] || project.language}
              </span>
              {project.category && (
                <span className="text-xs text-muted-foreground">
                  {categoryLabel(project.category)}
                </span>
              )}
            </div>
          </div>
          <Link
            href={`/results?projectId=${project.id}`}
            className="shrink-0 inline-flex items-center gap-1.5 rounded-lg bg-primary px-4 py-2 text-sm font-medium text-primary-foreground hover:bg-primary/90 transition-colors shadow-sm"
          >
            <Eye className="size-4" />
            查看完整结果
          </Link>
        </div>

        {/* Project Details Summary */}
        {(project.features ||
          project.sellingPoints ||
          project.keywords ||
          project.targetAudience) && (
          <Card className="mt-4">
            <CardContent className="pt-4 text-sm">
              <div className="grid gap-3 sm:grid-cols-2">
                {project.features && (
                  <div>
                    <span className="text-xs text-muted-foreground">产品特点</span>
                    <p className="mt-0.5">{project.features}</p>
                  </div>
                )}
                {project.sellingPoints && (
                  <div>
                    <span className="text-xs text-muted-foreground">核心卖点</span>
                    <p className="mt-0.5">{project.sellingPoints}</p>
                  </div>
                )}
                {project.keywords && (
                  <div>
                    <span className="text-xs text-muted-foreground">关键词</span>
                    <p className="mt-0.5">{project.keywords}</p>
                  </div>
                )}
                {project.targetAudience && (
                  <div>
                    <span className="text-xs text-muted-foreground">目标人群</span>
                    <p className="mt-0.5">{project.targetAudience}</p>
                  </div>
                )}
              </div>
            </CardContent>
          </Card>
        )}
      </div>

      {/* Generation Options */}
      <h2 className="text-lg font-semibold mb-4">选择要生成的内容</h2>
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3 mb-10">
        {generationTypes.map((type) => {
          const Icon = type.icon
          return (
            <button
              key={type.key}
              type="button"
              disabled={generating !== null}
              onClick={() => handleGenerate(type.key)}
              className={`group relative rounded-xl border ${type.borderColor} bg-gradient-to-br ${type.gradient} p-5 text-left transition-all hover:shadow-md hover:-translate-y-0.5 disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:translate-y-0`}
            >
              <div
                className={`flex size-10 items-center justify-center rounded-lg bg-background/80 ring-1 ring-border/50 mb-3 ${type.iconColor}`}
              >
                {generating === type.key ? (
                  <Loader2 className="size-5 animate-spin" />
                ) : (
                  <Icon className="size-5" />
                )}
              </div>
              <h3 className="font-semibold text-sm mb-1">{type.label}</h3>
              <p className="text-xs text-muted-foreground">{type.desc}</p>
            </button>
          )
        })}
      </div>

      {/* Generated Results */}
      {records.length > 0 && (
        <>
          <h2 className="text-lg font-semibold mb-4">生成记录</h2>
          <div className="space-y-4">
            {records.map((record) => (
              <Card key={record.id}>
                <CardHeader>
                  <div className="flex items-center justify-between">
                    <div>
                      <CardTitle className="text-sm">
                        {contentTypeLabels[record.contentType] || record.contentType}
                      </CardTitle>
                      <CardDescription className="text-xs mt-0.5">
                        {new Date(record.createdAt).toLocaleString("zh-CN")}
                      </CardDescription>
                    </div>
                    <div className="flex items-center gap-1">
                      <Button
                        variant="ghost"
                        size="icon-sm"
                        onClick={() => {
                          handleCopy(record.content || record.imageUrl)
                          setCopiedId(record.id)
                          setTimeout(() => setCopiedId(null), 2000)
                        }}
                        title="复制"
                      >
                        {copiedId === record.id ? (
                          <Check className="size-4 text-emerald-500" />
                        ) : (
                          <Copy className="size-4" />
                        )}
                      </Button>
                      <Button
                        variant="ghost"
                        size="icon-sm"
                        onClick={() => handleDelete(record.id)}
                        title="删除"
                        className="hover:text-destructive"
                      >
                        <Trash2 className="size-4" />
                      </Button>
                    </div>
                  </div>
                </CardHeader>
                <CardContent>
                  {record.content && (
                    <pre className="whitespace-pre-wrap text-sm font-sans text-foreground/90 leading-relaxed">
                      {record.content}
                    </pre>
                  )}
                  {record.imageUrl && (
                    <div className="mt-2">
                      <span className="text-sm text-muted-foreground">
                        {record.imageUrl}
                      </span>
                    </div>
                  )}
                </CardContent>
              </Card>
            ))}
          </div>
        </>
      )}
    </div>
  )
}

function categoryLabel(value: string): string {
  const map: Record<string, string> = {
    electronics: "电子产品",
    clothing: "服装鞋帽",
    home: "家居园艺",
    beauty: "美容个护",
    sports: "运动户外",
    toys: "玩具游戏",
    food: "食品饮料",
    other: "其他",
  }
  return map[value] || value
}
